import Foundation
import CRMCore

func runInboxLinkLeadChecks(directory:URL) async throws -> Int {
    var count=0
    func expect(_ v:Bool,_ m:String) throws {guard v else {throw CheckFailure(message:m)};count += 1}
    let d=try JSONSerialization.jsonObject(with:Data(contentsOf:directory.appendingPathComponent("inbox-link-lead.json"))) as! [String:Any],reads=APILeadReadRepository(transport:FixtureLeadReadTransport(directory:directory)),port=FixtureInboxLinkLeadPort(directory:directory)
    func context(_ x:[String:Int])->InboxConversationFilesContext {InboxConversationFilesContext(business:x["business"]!,conversation:x["conversation"]!,epoch:x["epoch"]!,revision:x["revision"]!)}
    func reference(_ c:InboxConversationFilesContext,id:Int=3701) async throws -> QualifiedLeadReference {
        var s=LeadReadSession();s.bind(c);s.show();s.update(" e\u{0301} ",input:s.input);let t=s.beginList(expected:s.control)!;let p=try await reads.leads(business:c.business,search:t.query);s.accept(p,ticket:t);let pt=s.beginProfile(id:id,expected:s.control)!;let profile=try await reads.lead(business:c.business,id:id);s.accept(profile,ticket:pt);s.use(expected:s.control);return s.choice!
    }
    for row in d["source_cases"] as! [[String:Any]] {let s=InboxLinkLeadSource.decode(Data((row["response_json"] as! String).utf8),context:context(row["context"] as! [String:Int]));try expect((s != nil)==row["valid"] as! Bool,"Lead link exact generic source/null/alias \(row["name"]!)");if let s {try expect(s.valid && Mirror(reflecting:s).children.count==4,"Link-lead source retained permission/version fields")}}
    let c=context(d["context"] as! [String:Int]),source=InboxLinkLeadSource.decode(Data((d["source_json"] as! String).utf8),context:c)!
    for row in d["candidate_scope_cases"] as! [[String:Any]] {let ctx=context(row["context"] as! [String:Int]),r=try await reference(ctx,id:ctx.business==101 ? 3701:4701);try expect((InboxLinkLeadCandidate(source:source,reference:r) != nil)==row["valid"] as! Bool,"Lead qualified reference owner \(row["name"]!)")}
    func review(_ c:InboxConversationFilesContext,_ raw:String) async throws -> InboxLinkLeadReview {let s=InboxLinkLeadSource.decode(Data(raw.utf8),context:c)!,r=try await reference(c),candidate=InboxLinkLeadCandidate(source:s,reference:r)!,auth=port.grants.compactMap {$0.authorization(for:c)}.first!;return InboxLinkLeadReview(source:s,authorization:auth,candidate:candidate,visit:1)}
    for row in d["receipt_cases"] as! [[String:Any]] {let r=try await review(context(row["source_context"] as! [String:Int]),row["source_json"] as! String);var l=InboxLinkLeadLedger();let a=l.begin(r)!;let value=InboxLinkLeadReceipt.decode(Data((row["response_json"] as! String).utf8),attempt:a);try expect((value != nil)==row["valid"] as! Bool,"Conditional client plain200 receipt \(row["name"]!)")}
    let r=try await review(c,d["source_json"] as! String),auth=r.authorization;var l=InboxLinkLeadLedger();let a=l.begin(r)!,body=try JSONSerialization.jsonObject(with:a.preparedBody()) as! [String:Int]
    try expect(body==["lead_id":3701] && a.path=="/api/inbox/conversations/901/link-lead/" && a.query.isEmpty && a.headers.isEmpty,"Lead link invented client/body/Business/key/version")
    try expect(l.begin(r)==nil && !l.acknowledge(auth,record:l.visible(auth)!),"Pending lead link repeated/acknowledged")
    l.complete(a,outcome:try await port.execute(a));let known=l.visible(auth)!;try expect(known.phase == .response && known.result?.source.lead==3701 && known.result?.source.client==701 && known.attempt.review.source.lead==81 && known.attempt.review.candidate.reference.detail.lead.client_id==1701,"Lead link overwrote existing different Client or mutated original")
    l.complete(a,outcome:.unknown);try expect(l.visible(auth)==known && l.acknowledge(auth,record:known),"Late duplicate or known lead ack changed history")
    let nc=context(d["null_context"] as! [String:Int]),nr=try await review(nc,d["null_source_json"] as! String);var nl=InboxLinkLeadLedger();let na=nl.begin(nr)!;nl.complete(na,outcome:try await port.execute(na));try expect(nl.visible(nr.authorization)?.result?.source.client==1701 && nr.source.client==nil,"Null original Client was not filled from qualified Lead")
    let u=l.begin(r)!;l.complete(u,outcome:.unknown);let unknown=l.visible(auth)!,next=InboxConversationFilesContext(business:101,conversation:901,epoch:2,revision:2),fresh=try await reference(next),matching=InboxLinkLeadSource.decode(try JSONSerialization.data(withJSONObject:["id":901, "business":101, "lead":3701, "client":701, "updated_at":"matching read"]),context:next)!,nAuth=port.grants[0].authorization(for:next)!,newReview=InboxLinkLeadReview(source:matching,authorization:nAuth,candidate:InboxLinkLeadCandidate(source:matching,reference:fresh)!,visit:2)
    try expect(l.visible(nAuth)==unknown && !l.acknowledge(nAuth,record:unknown) && l.begin(newReview)==nil && unknown.attempt==u && SourceTextIdentity.same(unknown.attempt.review.candidate.reference.rawQuery," e\u{0301} "),"Matching link/Client/GET/new epoch recovered unknown or changed raw input/attempt")
    let other=SyntheticInboxLinkLeadGrant(business:101,conversation:901,actor:6002,leadsUpdate:true,conversationsUpdate:true).authorization(for:next)!;try expect(l.visible(other)==nil && l.blocked(business:101,conversation:901) && !l.blocked(business:202,conversation:951),"Lead actor visibility or shared Business barrier")
    for grant in [SyntheticInboxLinkLeadGrant(business:101,conversation:901,actor:5001,leadsUpdate:false,conversationsUpdate:true),SyntheticInboxLinkLeadGrant(business:101,conversation:901,actor:5001,leadsUpdate:true,conversationsUpdate:false),SyntheticInboxLinkLeadGrant(business:101,conversation:902,actor:5001,leadsUpdate:true,conversationsUpdate:true),SyntheticInboxLinkLeadGrant(business:101,conversation:901,actor:0,leadsUpdate:true,conversationsUpdate:true)] {try expect(grant.authorization(for:c)==nil,"Missing/wrong one-of-two lead grant/actor authorized")}
    for status in [201,202,204,400,409,500] {var wrong=InboxLinkLeadLedger();let a=wrong.begin(r)!;wrong.complete(a,outcome:.response(status:status,data:try JSONSerialization.data(withJSONObject:["id":901,"business":101,"lead":3701,"client":701,"updated_at":"fake"])));try expect(wrong.visible(auth)?.phase == .unknown,"Non-plain200 link-lead response became known")}
    var rejected=InboxLinkLeadLedger();let rejectedAttempt=rejected.begin(r)!;rejected.complete(rejectedAttempt,outcome:.rejectedWithoutWrite);let reject=rejected.visible(auth)!;try expect(reject.phase == .rejected && rejected.acknowledge(auth,record:reject) && rejected.records.count==1,"Definite no-write rejection lost history")
    return count
}
